SELECT COUNT(CASE WHEN "CEO_SALARY" > %s THEN "__COL1" ELSE NULL END) FROM (SELECT (SELECT U0."SALARY" AS "SALARY" FROM "EXPRESSIONS_EMPLOYEE" U0 WHERE U0."ID" = ("EXPRESSIONS_COMPANY"."CEO_ID")) AS "CEO_SALARY", "EXPRESSIONS_COMPANY"."ID" AS "__COL1" FROM "EXPRESSIONS_COMPANY") subquery;
SELECT ((SELECT (1) AS "A" FROM "EXPRESSIONS_EXPERIMENT" FETCH FIRST 1 ROWS ONLY) IS NOT NULL) AS "EXISTS" FROM "EXPRESSIONS_EXPERIMENT";
SELECT (SELECT V0."ID" AS "PK" FROM "EXPRESSIONS_COMPANY" V0 WHERE (V0."CEO_ID" IN (SELECT U0."ID" AS "PK" FROM "EXPRESSIONS_EMPLOYEE" U0 WHERE U0."ID" = (V0."CEO_ID")) AND V0."CEO_ID" = ("EXPRESSIONS_EMPLOYEE"."ID"))) AS "CEO_COMPANY" FROM "EXPRESSIONS_EMPLOYEE";
SELECT CAST(%s AS INTEGER) AS "A" FROM "EXPRESSIONS_COMPANY" INNER JOIN "EXPRESSIONS_EMPLOYEE" ON ("EXPRESSIONS_COMPANY"."CEO_ID" = "EXPRESSIONS_EMPLOYEE"."ID") INNER JOIN "EXPRESSIONS_EMPLOYEE" T3 ON ("EXPRESSIONS_COMPANY"."POINT_OF_CONTACT_ID" = T3."ID") WHERE "EXPRESSIONS_COMPANY"."ID" IN (SELECT U0."ID" AS "PK" FROM "EXPRESSIONS_COMPANY" U0 WHERE (U0."NUM_CHAIRS" >= ("EXPRESSIONS_EMPLOYEE"."SALARY") AND U0."NUM_EMPLOYEES" >= (T3."SALARY"))) FETCH FIRST 1 ROWS ONLY;
SELECT CAST(%s AS INTEGER) AS "A" FROM "EXPRESSIONS_EMPLOYEE" FETCH FIRST 1 ROWS ONLY;
SELECT CAST(%s AS INTEGER) AS "A" FROM "EXPRESSIONS_EMPLOYEE" WHERE NOT (EXISTS(SELECT (1) AS "A" FROM "EXPRESSIONS_COMPANY" U0 WHERE U0."CEO_ID" = ("EXPRESSIONS_EMPLOYEE"."ID") FETCH FIRST 1 ROWS ONLY)) FETCH FIRST 1 ROWS ONLY;
SELECT CAST(%s AS INTEGER) AS "A" FROM "EXPRESSIONS_EMPLOYEE" WHERE "EXPRESSIONS_EMPLOYEE"."ID" IN (SELECT U0."CEO_ID" AS "CEO" FROM "EXPRESSIONS_COMPANY" U0 GROUP BY U0."CEO_ID") FETCH FIRST 1 ROWS ONLY;
SELECT CAST(%s AS INTEGER) AS "A" FROM "EXPRESSIONS_EXPERIMENT" WHERE (BIGINT(DAYS((SELECT U0."COMPLETED" AS "COMPLETED" FROM "EXPRESSIONS_EXPERIMENT" U0 WHERE U0."ID" = ("EXPRESSIONS_EXPERIMENT"."ID"))) - DAYS("EXPRESSIONS_EXPERIMENT"."COMPLETED")) * 86400000000) = %s FETCH FIRST 1 ROWS ONLY;
SELECT CAST(%s AS INTEGER) AS "A" FROM "EXPRESSIONS_EXPERIMENT" WHERE (BIGINT(DAYS((SELECT U0."START" AS "START" FROM "EXPRESSIONS_EXPERIMENT" U0 WHERE U0."ID" = ("EXPRESSIONS_EXPERIMENT"."ID"))) - DAYS("EXPRESSIONS_EXPERIMENT"."START")) * 86400000000 + BIGINT(MIDNIGHT_SECONDS((SELECT U0."START" AS "START" FROM "EXPRESSIONS_EXPERIMENT" U0 WHERE U0."ID" = ("EXPRESSIONS_EXPERIMENT"."ID"))) - MIDNIGHT_SECONDS("EXPRESSIONS_EXPERIMENT"."START")) * 1000000 + (MICROSECOND((SELECT U0."START" AS "START" FROM "EXPRESSIONS_EXPERIMENT" U0 WHERE U0."ID" = ("EXPRESSIONS_EXPERIMENT"."ID"))) - MICROSECOND("EXPRESSIONS_EXPERIMENT"."START"))) = %s FETCH FIRST 1 ROWS ONLY;
SELECT CAST(%s AS INTEGER) AS "A" FROM "EXPRESSIONS_NUMBER" WHERE EXISTS(SELECT (1) AS "A" FROM "EXPRESSIONS_NUMBER" U0 WHERE (NOT (U0."ID" = ("EXPRESSIONS_NUMBER"."ID")) AND U0."THE_INTEGER" BETWEEN U0."THE_INTEGER" AND U0."THE_INTEGER") FETCH FIRST 1 ROWS ONLY) FETCH FIRST 1 ROWS ONLY;
SELECT CAST(%s AS INTEGER) AS "A" FROM "EXPRESSIONS_RESULT" INNER JOIN "EXPRESSIONS_EXPERIMENT" ON ("EXPRESSIONS_RESULT"."EXPERIMENT_ID" = "EXPRESSIONS_EXPERIMENT"."ID") WHERE "EXPRESSIONS_RESULT"."ID" IN (SELECT U0."ID" AS "PK" FROM "EXPRESSIONS_RESULT" U0 WHERE U0."RESULT_TIME" >= ("EXPRESSIONS_EXPERIMENT"."ASSIGNED")) FETCH FIRST 1 ROWS ONLY;
SELECT CAST(%s AS INTEGER) AS "A" FROM "EXPRESSIONS_TIME" WHERE (BIGINT(MIDNIGHT_SECONDS((SELECT U0."TIME" AS "TIME" FROM "EXPRESSIONS_TIME" U0 WHERE U0."ID" = ("EXPRESSIONS_TIME"."ID"))) - MIDNIGHT_SECONDS("EXPRESSIONS_TIME"."TIME")) * 1000000) = %s FETCH FIRST 1 ROWS ONLY;
SELECT COUNT(*) AS "__COUNT" FROM "EXPRESSIONS_COMPANY" WHERE ("EXPRESSIONS_COMPANY"."NUM_EMPLOYEES" > %s);
