SELECT "EXPRESSIONS_COMPANY"."ID", "EXPRESSIONS_COMPANY"."NAME", "EXPRESSIONS_COMPANY"."NUM_EMPLOYEES", "EXPRESSIONS_COMPANY"."NUM_CHAIRS", "EXPRESSIONS_COMPANY"."CEO_ID", "EXPRESSIONS_COMPANY"."POINT_OF_CONTACT_ID", "EXPRESSIONS_COMPANY"."BASED_IN_EU", (SELECT U0."MANAGER_ID" AS "MANAGER" FROM "EXPRESSIONS_EMPLOYEE" U0 WHERE U0."LASTNAME" = ("EXPRESSIONS_EMPLOYEE"."LASTNAME")) AS "CEO_MANAGER" FROM "EXPRESSIONS_COMPANY" INNER JOIN "EXPRESSIONS_EMPLOYEE" ON ("EXPRESSIONS_COMPANY"."CEO_ID" = "EXPRESSIONS_EMPLOYEE"."ID") WHERE (SELECT U0."MANAGER_ID" AS "MANAGER" FROM "EXPRESSIONS_EMPLOYEE" U0 WHERE U0."LASTNAME" = ("EXPRESSIONS_EMPLOYEE"."LASTNAME")) = %s FETCH FIRST 21 ROWS ONLY;
SELECT "EXPRESSIONS_COMPANY"."ID", "EXPRESSIONS_COMPANY"."NAME", "EXPRESSIONS_COMPANY"."NUM_EMPLOYEES", "EXPRESSIONS_COMPANY"."NUM_CHAIRS", "EXPRESSIONS_COMPANY"."CEO_ID", "EXPRESSIONS_COMPANY"."POINT_OF_CONTACT_ID", "EXPRESSIONS_COMPANY"."BASED_IN_EU", CASE CAST(%s AS BOOLEAN) WHEN TRUE THEN FALSE WHEN FALSE THEN TRUE END AS "EU_REQUIRED" FROM "EXPRESSIONS_COMPANY" WHERE "EXPRESSIONS_COMPANY"."BASED_IN_EU" = (CASE CASE CAST(%s AS BOOLEAN) WHEN TRUE THEN FALSE WHEN FALSE THEN TRUE END WHEN TRUE THEN FALSE WHEN FALSE THEN TRUE END);
SELECT "EXPRESSIONS_COMPANY"."ID", "EXPRESSIONS_COMPANY"."NAME", "EXPRESSIONS_COMPANY"."NUM_EMPLOYEES", "EXPRESSIONS_COMPANY"."NUM_CHAIRS", "EXPRESSIONS_COMPANY"."CEO_ID", "EXPRESSIONS_COMPANY"."POINT_OF_CONTACT_ID", "EXPRESSIONS_COMPANY"."BASED_IN_EU", CASE CAST(%s AS BOOLEAN) WHEN TRUE THEN FALSE WHEN FALSE THEN TRUE END AS "EU_REQUIRED" FROM "EXPRESSIONS_COMPANY" WHERE "EXPRESSIONS_COMPANY"."BASED_IN_EU" = (CASE CAST(%s AS BOOLEAN) WHEN TRUE THEN FALSE WHEN FALSE THEN TRUE END) ORDER BY 8 ASC;
