SELECT "EXPRESSIONS_COMPANY"."NAME" AS "NAME" FROM "EXPRESSIONS_COMPANY" INNER JOIN "EXPRESSIONS_EMPLOYEE" ON ("EXPRESSIONS_COMPANY"."CEO_ID" = "EXPRESSIONS_EMPLOYEE"."ID") WHERE EXISTS(SELECT (1) AS "A" FROM "EXPRESSIONS_COMPANY" U0 INNER JOIN "EXPRESSIONS_EMPLOYEE" U1 ON (U0."CEO_ID" = U1."ID") WHERE U0."NAME" LIKE REPLACE(REPLACE(REPLACE((SUBSTRING("EXPRESSIONS_EMPLOYEE"."FIRSTNAME", CAST(%s AS INTEGER), CAST(%s AS INTEGER))), '\', '\\'), '%%', '\%%'), '_', '\_') || '%%' ESCAPE '\' FETCH FIRST 1 ROWS ONLY);
