SELECT "EXPRESSIONS_EMPLOYEE"."FIRSTNAME" AS "FIRSTNAME", ((SELECT (1) AS "A" FROM "EXPRESSIONS_COMPANY" U0 WHERE U0."POINT_OF_CONTACT_ID" = ("EXPRESSIONS_EMPLOYEE"."ID") FETCH FIRST 1 ROWS ONLY) IS NOT NULL) AS "IS_POINT_OF_CONTACT", NOT ((SELECT (1) AS "A" FROM "EXPRESSIONS_COMPANY" U0 WHERE U0."POINT_OF_CONTACT_ID" = ("EXPRESSIONS_EMPLOYEE"."ID") FETCH FIRST 1 ROWS ONLY) IS NOT NULL) AS "IS_NOT_POINT_OF_CONTACT", ((SELECT (1) AS "A" FROM "EXPRESSIONS_COMPANY" U0 WHERE (U0."CEO_ID" = ("EXPRESSIONS_EMPLOYEE"."ID") AND U0."NUM_EMPLOYEES" < %s) FETCH FIRST 1 ROWS ONLY) IS NOT NULL) AS "IS_CEO_OF_SMALL_COMPANY", ((SELECT (1) AS "A" FROM "EXPRESSIONS_COMPANY" U0 WHERE (U0."CEO_ID" = ("EXPRESSIONS_EMPLOYEE"."ID") AND U0."NUM_EMPLOYEES" < %s) FETCH FIRST 1 ROWS ONLY) IS NOT NULL) AS "IS_CEO_SMALL_2", (SELECT U0."NAME" AS "NAME" FROM "EXPRESSIONS_COMPANY" U0 WHERE (U0."CEO_ID" = ("EXPRESSIONS_EMPLOYEE"."ID") OR U0."POINT_OF_CONTACT_ID" = ("EXPRESSIONS_EMPLOYEE"."ID")) ORDER BY U0."NUM_EMPLOYEES" DESC FETCH FIRST 1 ROWS ONLY) AS "LARGEST_COMPANY" FROM "EXPRESSIONS_EMPLOYEE" ORDER BY 1 ASC;
