SELECT "EXPRESSIONS_EMPLOYEE"."ID", "EXPRESSIONS_EMPLOYEE"."FIRSTNAME", "EXPRESSIONS_EMPLOYEE"."LASTNAME", "EXPRESSIONS_EMPLOYEE"."SALARY", "EXPRESSIONS_EMPLOYEE"."MANAGER_ID", "EXPRESSIONS_EMPLOYEE"."BASED_IN_EU" FROM "EXPRESSIONS_EMPLOYEE" WHERE "EXPRESSIONS_EMPLOYEE"."LASTNAME" LIKE REPLACE(REPLACE(REPLACE(("EXPRESSIONS_EMPLOYEE"."FIRSTNAME"), '\', '\\'), '%%', '\%%'), '_', '\_') || '%%' ESCAPE '\';
SELECT "EXPRESSIONS_EMPLOYEE"."ID", "EXPRESSIONS_EMPLOYEE"."FIRSTNAME", "EXPRESSIONS_EMPLOYEE"."LASTNAME", "EXPRESSIONS_EMPLOYEE"."SALARY", "EXPRESSIONS_EMPLOYEE"."MANAGER_ID", "EXPRESSIONS_EMPLOYEE"."BASED_IN_EU", ((SELECT (1) AS "A" FROM "EXPRESSIONS_COMPANY" U0 WHERE U0."CEO_ID" = ("EXPRESSIONS_EMPLOYEE"."ID") FETCH FIRST 1 ROWS ONLY) IS NOT NULL) AS "FOUND" FROM "EXPRESSIONS_EMPLOYEE" WHERE EXISTS(SELECT (1) AS "A" FROM "EXPRESSIONS_COMPANY" U0 WHERE U0."CEO_ID" = ("EXPRESSIONS_EMPLOYEE"."ID") FETCH FIRST 1 ROWS ONLY);
SELECT "EXPRESSIONS_EMPLOYEE"."ID", "EXPRESSIONS_EMPLOYEE"."FIRSTNAME", "EXPRESSIONS_EMPLOYEE"."LASTNAME", "EXPRESSIONS_EMPLOYEE"."SALARY", "EXPRESSIONS_EMPLOYEE"."MANAGER_ID", "EXPRESSIONS_EMPLOYEE"."BASED_IN_EU", ((SELECT (1) AS "A" FROM "EXPRESSIONS_COMPANY" U0 WHERE U0."POINT_OF_CONTACT_ID" = ("EXPRESSIONS_EMPLOYEE"."ID") FETCH FIRST 1 ROWS ONLY) IS NOT NULL) AS "IS_POINT_OF_CONTACT" FROM "EXPRESSIONS_EMPLOYEE";
SELECT "EXPRESSIONS_EMPLOYEE"."ID", "EXPRESSIONS_EMPLOYEE"."FIRSTNAME", "EXPRESSIONS_EMPLOYEE"."LASTNAME", "EXPRESSIONS_EMPLOYEE"."SALARY", "EXPRESSIONS_EMPLOYEE"."MANAGER_ID", "EXPRESSIONS_EMPLOYEE"."BASED_IN_EU", (BITOR(LENGTH("EXPRESSIONS_EMPLOYEE"."LASTNAME"), CAST(%s AS INTEGER))) AS "BITOR" FROM "EXPRESSIONS_EMPLOYEE" FETCH FIRST 21 ROWS ONLY;
