SELECT "EXPRESSIONS_EXPERIMENT"."ID", "EXPRESSIONS_EXPERIMENT"."NAME", "EXPRESSIONS_EXPERIMENT"."ASSIGNED", "EXPRESSIONS_EXPERIMENT"."COMPLETED", "EXPRESSIONS_EXPERIMENT"."ESTIMATED_TIME", "EXPRESSIONS_EXPERIMENT"."START", "EXPRESSIONS_EXPERIMENT"."END", "EXPRESSIONS_EXPERIMENT"."SCALAR", ("EXPRESSIONS_EXPERIMENT"."ESTIMATED_TIME" + CAST(%s AS BIGINT)) AS "DURATION" FROM "EXPRESSIONS_EXPERIMENT" ORDER BY "EXPRESSIONS_EXPERIMENT"."NAME" ASC;
SELECT "EXPRESSIONS_EXPERIMENT"."ID", "EXPRESSIONS_EXPERIMENT"."NAME", "EXPRESSIONS_EXPERIMENT"."ASSIGNED", "EXPRESSIONS_EXPERIMENT"."COMPLETED", "EXPRESSIONS_EXPERIMENT"."ESTIMATED_TIME", "EXPRESSIONS_EXPERIMENT"."START", "EXPRESSIONS_EXPERIMENT"."END", "EXPRESSIONS_EXPERIMENT"."SCALAR", ("EXPRESSIONS_EXPERIMENT"."START" + INTEGER((CAST(%s AS BIGINT)) / 86400000000) DAYS + MOD((CAST(%s AS BIGINT)), 86400000000) MICROSECONDS) AS "DT" FROM "EXPRESSIONS_EXPERIMENT" ORDER BY "EXPRESSIONS_EXPERIMENT"."NAME" ASC;
SELECT "EXPRESSIONS_EXPERIMENT"."ID", "EXPRESSIONS_EXPERIMENT"."NAME", "EXPRESSIONS_EXPERIMENT"."ASSIGNED", "EXPRESSIONS_EXPERIMENT"."COMPLETED", "EXPRESSIONS_EXPERIMENT"."ESTIMATED_TIME", "EXPRESSIONS_EXPERIMENT"."START", "EXPRESSIONS_EXPERIMENT"."END", "EXPRESSIONS_EXPERIMENT"."SCALAR", ("EXPRESSIONS_EXPERIMENT"."START" + INTEGER((CAST(NULL AS BIGINT)) / 86400000000) DAYS + MOD((CAST(NULL AS BIGINT)), 86400000000) MICROSECONDS) AS "SHIFTED" FROM "EXPRESSIONS_EXPERIMENT" ORDER BY "EXPRESSIONS_EXPERIMENT"."NAME" ASC FETCH FIRST 1 ROWS ONLY;
SELECT "EXPRESSIONS_EXPERIMENT"."ID", "EXPRESSIONS_EXPERIMENT"."NAME", "EXPRESSIONS_EXPERIMENT"."ASSIGNED", "EXPRESSIONS_EXPERIMENT"."COMPLETED", "EXPRESSIONS_EXPERIMENT"."ESTIMATED_TIME", "EXPRESSIONS_EXPERIMENT"."START", "EXPRESSIONS_EXPERIMENT"."END", "EXPRESSIONS_EXPERIMENT"."SCALAR", ("EXPRESSIONS_EXPERIMENT"."START" + INTEGER(("EXPRESSIONS_EXPERIMENT"."ESTIMATED_TIME") / 86400000000) DAYS + MOD(("EXPRESSIONS_EXPERIMENT"."ESTIMATED_TIME"), 86400000000) MICROSECONDS) AS "ESTIMATED_END" FROM "EXPRESSIONS_EXPERIMENT" ORDER BY "EXPRESSIONS_EXPERIMENT"."NAME" ASC;
SELECT "EXPRESSIONS_EXPERIMENT"."ID", "EXPRESSIONS_EXPERIMENT"."NAME", "EXPRESSIONS_EXPERIMENT"."ASSIGNED", "EXPRESSIONS_EXPERIMENT"."COMPLETED", "EXPRESSIONS_EXPERIMENT"."ESTIMATED_TIME", "EXPRESSIONS_EXPERIMENT"."START", "EXPRESSIONS_EXPERIMENT"."END", "EXPRESSIONS_EXPERIMENT"."SCALAR", ("EXPRESSIONS_EXPERIMENT"."START" - INTEGER((CAST(NULL AS BIGINT)) / 86400000000) DAYS - MOD((CAST(NULL AS BIGINT)), 86400000000) MICROSECONDS) AS "SHIFTED" FROM "EXPRESSIONS_EXPERIMENT" ORDER BY "EXPRESSIONS_EXPERIMENT"."NAME" ASC FETCH FIRST 1 ROWS ONLY;
SELECT "EXPRESSIONS_EXPERIMENT"."ID", "EXPRESSIONS_EXPERIMENT"."NAME", "EXPRESSIONS_EXPERIMENT"."ASSIGNED", "EXPRESSIONS_EXPERIMENT"."COMPLETED", "EXPRESSIONS_EXPERIMENT"."ESTIMATED_TIME", "EXPRESSIONS_EXPERIMENT"."START", "EXPRESSIONS_EXPERIMENT"."END", "EXPRESSIONS_EXPERIMENT"."SCALAR", CASE WHEN "EXPRESSIONS_EXPERIMENT"."NAME" = %s THEN "EXPRESSIONS_EXPERIMENT"."COMPLETED" ELSE NULL END AS "DATE_CASE", CAST(%s AS DATE) AS "COMPLETED_VALUE", (BIGINT(DAYS(CASE WHEN "EXPRESSIONS_EXPERIMENT"."NAME" = %s THEN "EXPRESSIONS_EXPERIMENT"."COMPLETED" ELSE NULL END) - DAYS(CAST(%s AS DATE))) * 86400000000) AS "DIFFERENCE" FROM "EXPRESSIONS_EXPERIMENT" WHERE (BIGINT(DAYS(CASE WHEN ("EXPRESSIONS_EXPERIMENT"."NAME" = %s) THEN "EXPRESSIONS_EXPERIMENT"."COMPLETED" ELSE NULL END) - DAYS(CAST(%s AS DATE))) * 86400000000) = %s FETCH FIRST 21 ROWS ONLY;
SELECT "EXPRESSIONS_MANAGER"."ID", "EXPRESSIONS_MANAGER"."NAME", "EXPRESSIONS_MANAGER"."SECRETARY_ID" FROM "EXPRESSIONS_MANAGER" WHERE (NOT CAST(%s AS BOOLEAN) AND "EXPRESSIONS_MANAGER"."ID" = %s);
SELECT "EXPRESSIONS_MANAGER"."ID", "EXPRESSIONS_MANAGER"."NAME", "EXPRESSIONS_MANAGER"."SECRETARY_ID" FROM "EXPRESSIONS_MANAGER" WHERE "EXPRESSIONS_MANAGER"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT "EXPRESSIONS_MANAGER"."ID", "EXPRESSIONS_MANAGER"."NAME", "EXPRESSIONS_MANAGER"."SECRETARY_ID", CAST(%s AS BOOLEAN) AS "EXISTS" FROM "EXPRESSIONS_MANAGER" WHERE (NOT CAST(%s AS BOOLEAN) AND "EXPRESSIONS_MANAGER"."ID" = %s) FETCH FIRST 21 ROWS ONLY;
SELECT "EXPRESSIONS_MANAGER"."ID", "EXPRESSIONS_MANAGER"."NAME", "EXPRESSIONS_MANAGER"."SECRETARY_ID", CAST(%s AS BOOLEAN) AS "EXISTS" FROM "EXPRESSIONS_MANAGER" WHERE (NOT CAST(%s AS BOOLEAN) AND "EXPRESSIONS_MANAGER"."ID" = %s);
SELECT "EXPRESSIONS_MANAGER"."ID", "EXPRESSIONS_MANAGER"."NAME", "EXPRESSIONS_MANAGER"."SECRETARY_ID", NOT CAST(%s AS BOOLEAN) AS "NOT_EXISTS" FROM "EXPRESSIONS_MANAGER" WHERE "EXPRESSIONS_MANAGER"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT "EXPRESSIONS_MANAGER"."ID", "EXPRESSIONS_MANAGER"."NAME", "EXPRESSIONS_MANAGER"."SECRETARY_ID", NOT CAST(%s AS BOOLEAN) AS "NOT_EXISTS" FROM "EXPRESSIONS_MANAGER" WHERE "EXPRESSIONS_MANAGER"."ID" = %s;
SELECT "EXPRESSIONS_NUMBER"."ID", "EXPRESSIONS_NUMBER"."DECIMAL_VALUE" FROM "EXPRESSIONS_NUMBER" WHERE "EXPRESSIONS_NUMBER"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT "EXPRESSIONS_NUMBER"."ID", "EXPRESSIONS_NUMBER"."THE_INTEGER", "EXPRESSIONS_NUMBER"."THE_FLOAT", "EXPRESSIONS_NUMBER"."DECIMAL_VALUE" FROM "EXPRESSIONS_NUMBER" WHERE NOT ("EXPRESSIONS_NUMBER"."THE_FLOAT" = ("EXPRESSIONS_NUMBER"."THE_INTEGER") AND "EXPRESSIONS_NUMBER"."THE_FLOAT" IS NOT NULL);
SELECT "EXPRESSIONS_NUMBER"."ID", "EXPRESSIONS_NUMBER"."THE_INTEGER", "EXPRESSIONS_NUMBER"."THE_FLOAT", "EXPRESSIONS_NUMBER"."DECIMAL_VALUE" FROM "EXPRESSIONS_NUMBER" WHERE "EXPRESSIONS_NUMBER"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT "EXPRESSIONS_NUMBER"."ID", "EXPRESSIONS_NUMBER"."THE_INTEGER", "EXPRESSIONS_NUMBER"."THE_FLOAT", "EXPRESSIONS_NUMBER"."DECIMAL_VALUE" FROM "EXPRESSIONS_NUMBER" WHERE "EXPRESSIONS_NUMBER"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT "EXPRESSIONS_NUMBER"."ID", "EXPRESSIONS_NUMBER"."THE_INTEGER", "EXPRESSIONS_NUMBER"."THE_FLOAT", "EXPRESSIONS_NUMBER"."DECIMAL_VALUE" FROM "EXPRESSIONS_NUMBER" WHERE "EXPRESSIONS_NUMBER"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT "EXPRESSIONS_NUMBER"."ID", "EXPRESSIONS_NUMBER"."THE_INTEGER", "EXPRESSIONS_NUMBER"."THE_FLOAT", "EXPRESSIONS_NUMBER"."DECIMAL_VALUE" FROM "EXPRESSIONS_NUMBER" WHERE "EXPRESSIONS_NUMBER"."ID" = ("EXPRESSIONS_NUMBER"."ID") FETCH FIRST 21 ROWS ONLY;
SELECT "EXPRESSIONS_NUMBER"."ID", "EXPRESSIONS_NUMBER"."THE_INTEGER", "EXPRESSIONS_NUMBER"."THE_FLOAT", "EXPRESSIONS_NUMBER"."DECIMAL_VALUE" FROM "EXPRESSIONS_NUMBER";
SELECT "EXPRESSIONS_NUMBER"."ID", "EXPRESSIONS_NUMBER"."THE_INTEGER", "EXPRESSIONS_NUMBER"."THE_FLOAT", "EXPRESSIONS_NUMBER"."DECIMAL_VALUE", (SELECT COUNT(U0."SALARY") AS "CNT" FROM "EXPRESSIONS_EMPLOYEE" U0 WHERE U0."SALARY" = ("EXPRESSIONS_NUMBER"."THE_INTEGER") GROUP BY U0."ID", U0."FIRSTNAME", U0."LASTNAME", U0."SALARY", U0."MANAGER_ID", U0."BASED_IN_EU" HAVING COUNT(U0."SALARY") > %s FETCH FIRST 1 ROWS ONLY) AS "MIN_VALUABLE_COUNT" FROM "EXPRESSIONS_NUMBER" FETCH FIRST 21 ROWS ONLY;
SELECT "EXPRESSIONS_NUMBER"."ID", "EXPRESSIONS_NUMBER"."THE_INTEGER", "EXPRESSIONS_NUMBER"."THE_FLOAT", "EXPRESSIONS_NUMBER"."DECIMAL_VALUE", CAST(%s AS INTEGER) AS "X" FROM "EXPRESSIONS_NUMBER" WHERE ("EXPRESSIONS_NUMBER"."THE_INTEGER" = %s AND CAST(%s AS INTEGER) = CAST(%s AS DECIMAL(1, 0)) AND CAST(%s AS INTEGER) = CAST(%s AS DECIMAL(1, 0)));
SELECT "EXPRESSIONS_RESULT"."ID", "EXPRESSIONS_RESULT"."EXPERIMENT_ID", "EXPRESSIONS_RESULT"."RESULT_TIME" FROM "EXPRESSIONS_RESULT" INNER JOIN "EXPRESSIONS_EXPERIMENT" ON ("EXPRESSIONS_RESULT"."EXPERIMENT_ID" = "EXPRESSIONS_EXPERIMENT"."ID") WHERE DATE("EXPRESSIONS_RESULT"."RESULT_TIME") BETWEEN DATE("EXPRESSIONS_EXPERIMENT"."START") AND DATE("EXPRESSIONS_EXPERIMENT"."END");
SELECT "EXPRESSIONS_RESULT"."ID", "EXPRESSIONS_RESULT"."EXPERIMENT_ID", "EXPRESSIONS_RESULT"."RESULT_TIME" FROM "EXPRESSIONS_RESULT" INNER JOIN "EXPRESSIONS_EXPERIMENT" ON ("EXPRESSIONS_RESULT"."EXPERIMENT_ID" = "EXPRESSIONS_EXPERIMENT"."ID") WHERE "EXPRESSIONS_RESULT"."RESULT_TIME" BETWEEN "EXPRESSIONS_EXPERIMENT"."START" AND "EXPRESSIONS_EXPERIMENT"."END";
SELECT "EXPRESSIONS_SIMULATIONRUN"."ID", "EXPRESSIONS_SIMULATIONRUN"."START_ID", "EXPRESSIONS_SIMULATIONRUN"."END_ID", "EXPRESSIONS_SIMULATIONRUN"."MIDPOINT" FROM "EXPRESSIONS_SIMULATIONRUN" INNER JOIN "EXPRESSIONS_TIME" ON ("EXPRESSIONS_SIMULATIONRUN"."START_ID" = "EXPRESSIONS_TIME"."ID") INNER JOIN "EXPRESSIONS_TIME" T3 ON ("EXPRESSIONS_SIMULATIONRUN"."END_ID" = T3."ID") WHERE "EXPRESSIONS_SIMULATIONRUN"."MIDPOINT" BETWEEN "EXPRESSIONS_TIME"."TIME" AND T3."TIME";
SELECT "EXPRESSIONS_SIMULATIONRUN"."ID", "EXPRESSIONS_SIMULATIONRUN"."START_ID", "EXPRESSIONS_SIMULATIONRUN"."END_ID", "EXPRESSIONS_SIMULATIONRUN"."MIDPOINT" FROM "EXPRESSIONS_SIMULATIONRUN" LEFT OUTER JOIN "EXPRESSIONS_TIME" ON ("EXPRESSIONS_SIMULATIONRUN"."START_ID" = "EXPRESSIONS_TIME"."ID") LEFT OUTER JOIN "EXPRESSIONS_TIME" T3 ON ("EXPRESSIONS_SIMULATIONRUN"."END_ID" = T3."ID") WHERE NOT ("EXPRESSIONS_SIMULATIONRUN"."MIDPOINT" BETWEEN "EXPRESSIONS_TIME"."TIME" AND T3."TIME");
