SELECT "EXPRESSIONS_TIME"."ID", "EXPRESSIONS_TIME"."TIME" FROM "EXPRESSIONS_TIME" WHERE "EXPRESSIONS_TIME"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT "EXPRESSIONS_TIME"."ID", "EXPRESSIONS_TIME"."TIME", (SELECT (SELECT U0."START_ID" AS "START" FROM "EXPRESSIONS_SIMULATIONRUN" U0 WHERE U0."START_ID" = ("EXPRESSIONS_TIME"."ID")) AS "OTHER" FROM "EXPRESSIONS_TIME" V0 FETCH FIRST 1 ROWS ONLY) AS "OTHER" FROM "EXPRESSIONS_TIME";
SELECT "EXPRESSIONS_TIME"."ID", "EXPRESSIONS_TIME"."TIME", (SELECT (SELECT U0."TIME" AS "TIME" FROM "EXPRESSIONS_TIME" U0 WHERE (U0."ID" = (V0."START_ID") AND U0."TIME" = ("EXPRESSIONS_TIME"."TIME"))) AS "OTHER" FROM "EXPRESSIONS_SIMULATIONRUN" V0 FETCH FIRST 1 ROWS ONLY) AS "OTHER" FROM "EXPRESSIONS_TIME";
SELECT "EXPRESSIONS_TIME"."ID", "EXPRESSIONS_TIME"."TIME", CAST(%s AS DECIMAL(1, 0)) AS "ONE" FROM "EXPRESSIONS_TIME" ORDER BY "EXPRESSIONS_TIME"."ID" ASC FETCH FIRST 1 ROWS ONLY;
